// Qué anuncios se miran. Del Sheet, no de una variable global: es la
// lección del CAPI_DATASET, donde un valor único para dos canales acertaba
// por azar en uno y mentía en el otro.
const paginas  = $('Leer Paginas').all().map(i => i.json);
const anuncios = $('Leer Anuncios').all().map(i => i.json);
const si = (v) => String(v == null ? '' : v).trim().toUpperCase() === 'SI';

// CONTROL POR PÁGINA. Por defecto NINGUNA contesta: solo las marcadas a SI.
const activas = new Set(paginas.filter(p => si(p.activo)).map(p => String(p.page_id).trim()));

const problemas = [];
const buenos = [];
for (const a of anuncios) {
  if (!si(a.activo)) continue;
  const page_id = String(a.page_id || '').trim();
  if (!activas.has(page_id)) continue;              // página apagada: ni se mira
  // Una caída a un valor por defecto TIENE que avisar.
  if (!String(a.producto_id || '').trim()) { problemas.push(a.ad_id + ' — sin producto_id'); continue; }
  if (!String(a.wa_destino || '').trim())  { problemas.push(a.ad_id + ' — sin wa_destino');  continue; }
  if (!String(a.story_id   || '').trim())  { problemas.push(a.ad_id + ' — sin story_id');    continue; }
  buenos.push({ ad_id: String(a.ad_id).trim(), page_id, story_id: String(a.story_id).trim(),
                producto_id: String(a.producto_id).trim(), wa_destino: String(a.wa_destino).trim() });
}
if (!buenos.length) return [];

const porPagina = [...new Set(buenos.map(a => a.page_id))];
return porPagina.map(page_id => ({ json: {
  page_id, ventana_horas: 48,
  anuncios: buenos.filter(a => a.page_id === page_id),
  __problemas: problemas,
} }));

// Expande a una fila por anuncio, cada una con el token de SU página.
const tokens = $input.all();
const ciclos = $('Ciclo').all();
const salida = [];
for (let i = 0; i < ciclos.length; i++) {
  const c = ciclos[i].json;
  const t = tokens[i] && tokens[i].json;
  if (!t || !t.access_token) {
    throw new Error('La página ' + c.page_id + ' no devolvió access_token. ' +
      '¿Sigue asignada al usuario de sistema con la tarea MODERATE?');
  }
  for (const a of c.anuncios) {
    // UN POST, UNA VEZ. Medido el 6/9/2026: 12 anuncios daban solo 10 posts
    // distintos, porque varios anuncios (copias del mismo creativo) apuntan
    // al MISMO post oscuro. Esto ahorra la llamada; la deduplicación DE
    // VERDAD la hace 'Juntar comentarios', porque dos posts con id distinto
    // pueden devolver el mismo conjunto de comentarios y eso aquí no se sabe.
    const suf = String(a.story_id).split('_')[1];
    const yaEsta = salida.find(s => String(s.json.story_id).split('_')[1] === suf);
    if (yaEsta) {
      if (yaEsta.json.producto_id !== a.producto_id) {
        throw new Error('El post ' + a.story_id + ' lo comparten los anuncios ' + yaEsta.json.ad_id +
          ' y ' + a.ad_id + ', pero con productos distintos (' + yaEsta.json.producto_id + ' vs ' +
          a.producto_id + '). Arréglalo en el Sheet: no puedo elegir por ti.');
      }
      continue;
    }
    salida.push({ json: { ...a, page_id: c.page_id, ventana_horas: c.ventana_horas, page_token: t.access_token } });
  }
}
if (!salida.length) throw new Error('Ningún anuncio que mirar después de resolver los tokens.');
return salida;

// CASAR CADA RESPUESTA CON SU ANUNCIO, Y DEDUPLICAR POR CONJUNTO REAL.
//
// ⚠️ Lo que se descubrió el 6/9/2026 midiendo, y que no está en ninguna
// documentación: el id de un comentario NO empieza por el id del post que has
// pedido. Empieza por el id del OBJETO MULTIMEDIA:
//
//   pides  ...1703257091504796  ->  comentarios con prefijo 1699707728526399
//   pides  ...1699707728526399  ->  comentarios con prefijo 1699707728526399
//   pides  ...1715467166950455  ->  comentarios con prefijo 1656915486138957
//
// O sea que DOS POSTS DISTINTOS DEVUELVEN LOS MISMOS COMENTARIOS cuando
// reutilizan el mismo creativo. Deduplicar por story_id NO basta: hay que
// deduplicar por el conjunto de comentarios de verdad, que solo se conoce
// después de leerlo. Sin esto se contesta dos y tres veces al mismo
// comentario, desde anuncios distintos, y en público.
//
// El emparejado por índice SÍ es correcto (n8n devuelve una respuesta por
// item y en orden), pero se comprueba en vez de suponerlo.
const anuncios = $('Anuncios con token').all().map(i => i.json);
const res = $input.all();
if (res.length !== anuncios.length) {
  throw new Error('Llegaron ' + res.length + ' respuestas para ' + anuncios.length +
    ' anuncios. No sigo: emparejar a ciegas mandaría el enlace de otro producto.');
}

const salida = [];
const conjuntos = new Map();
for (let i = 0; i < anuncios.length; i++) {
  const a = anuncios[i];
  const r = (res[i] && res[i].json) || { data: [] };
  const datos = r.data || [];
  if (!datos.length) continue;                    // sin comentarios: no aporta nada

  const conjunto = String(datos[0].id).split('_')[0];
  const ya = conjuntos.get(conjunto);
  if (ya) {
    if (ya.producto_id !== a.producto_id) {
      throw new Error('Los anuncios ' + ya.ad_id + ' y ' + a.ad_id + ' comparten los MISMOS ' +
        'comentarios pero tienen productos distintos en el Sheet (' + ya.producto_id + ' vs ' +
        a.producto_id + '). Arréglalo: no puedo elegir por ti.');
    }
    continue;                                     // mismo conjunto, ya procesado
  }
  conjuntos.set(conjunto, a);
  salida.push({ json: { ...a, conjunto, respuesta: r } });
}
return salida;

// FILTRO DE ENTRADA + LÍMITE POR ANUNCIO
// ────────────────────────────────────────────────────────────────────
// Lógica INCRUSTADA desde fb/logica-comentarios.js. No la edites aquí:
// edita el fichero y relanza construir-comentarios-fb.js, o el ensayo y
// producción dejarán de decir lo mismo.
// ────────────────────────────────────────────────────────────────────

/**
 * LÓGICA DEL AGENTE DE COMENTARIOS DE FACEBOOK
 *
 * Funciones puras, sin E/S. Es la MISMA fuente que:
 *   - corre en el ciclo en seco (fb/ciclo-seco.js)
 *   - se incrusta en los nodos Code de n8n (la mete construir-comentarios-fb.js)
 *
 * Que sea una sola fuente no es cosmética: si la lógica del ensayo y la de
 * producción se escriben dos veces, el CSV que apruebas no prueba nada sobre
 * lo que el agente hará después.
 *
 * Nada aquí llama a la red ni lee un fichero. Todo entra por parámetro.
 */


// ─── Constantes de negocio ──────────────────────────────────────────────────
// Van aquí y NO en el prompt: son decisiones de negocio (regla 5).
const VENTANA_HORAS          = 48;   // nada más viejo se toca. Esto es la "fecha de corte"
const LIMITE_ANUNCIO_HORA    = 5;
const LIMITE_ANUNCIO_DIA     = 20;
// EN 1 A PROPÓSITO mientras se ve la primera respuesta real en público. Sube
// a 10 cuando esa primera esté revisada y aprobada. Es el tope de TODO el
// ciclo, sumando todas las páginas y todos los anuncios.
const LIMITE_CICLO           = 1;
const MAX_LONGITUD_RESPUESTA = 400;
const MIN_CARACTERES_UTILES  = 3;

// ─── Normalizador ───────────────────────────────────────────────────────────
// Misma semántica que el `normalizar()` del agente de WhatsApp: minúsculas,
// sin tildes y SIN EMOJIS. Ojo: eso último es justo lo que hace que un
// comentario que solo lleva emojis se quede vacío, que es lo que queremos.
function normalizar(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ─── Filtro de ENTRADA ──────────────────────────────────────────────────────
/**
 * Decide si un comentario merece siquiera gastar una llamada al modelo.
 * Determinista, sin modelo, y cada descarte deja su motivo.
 *
 * `comentario` es el objeto tal cual lo devuelve Meta con
 *   fields=id,message,created_time,comments{id,from,created_time}
 */
function filtroEntrada(comentario, opciones) {
  const { ahora, pageId, ventanaHoras = VENTANA_HORAS } = opciones;

  // 1. Vacío. El comentario '' que vimos en producción es real: probablemente
  //    un sticker. Tiene que caer aquí sin romper nada.
  const crudo = comentario.message;
  if (crudo == null || String(crudo).trim() === '') {
    return { pasa: false, motivo: 'vacio' };
  }

  // 2. Solo emojis / solo signos. Tras normalizar no queda nada que clasificar.
  const texto = normalizar(crudo);
  if (!texto) return { pasa: false, motivo: 'sin_texto' };

  // 3. Demasiado corto para significar algo. "ok", "?" no son una pregunta.
  const utiles = texto.replace(/[^a-z0-9ñ]/g, '');
  if (utiles.length < MIN_CARACTERES_UTILES) {
    return { pasa: false, motivo: 'demasiado_corto' };
  }

  // 4. Fuera de la ventana. Sustituye a la columna `arrancado_en` que tendría
  //    una tabla: sin estado, y los 239 comentarios acumulados quedan fuera
  //    solos porque todos son más viejos que esto.
  const creado = Date.parse(comentario.created_time);
  if (!Number.isFinite(creado)) return { pasa: false, motivo: 'sin_fecha' };
  const horas = (ahora - creado) / 3600000;
  if (horas > ventanaHoras) return { pasa: false, motivo: 'anterior_al_corte' };
  if (horas < 0) return { pasa: false, motivo: 'fecha_futura' };

  // 5. Lo escribió una PÁGINA, no una persona.
  //    Medido el 6/9/2026 sobre 100 comentarios reales: `from` viene VACÍO en
  //    los de personas y CON VALOR cuando comenta una Página. La ausencia de
  //    identidad, que es un incordio para todo lo demás, resulta ser el
  //    detector de spam más fiable que tenemos: el spam en chino de la página
  //    "Honeydiy" traía `from` y ningún cliente real lo traía.
  if (comentario.from && comentario.from.id) {
    return {
      pasa: false,
      motivo: comentario.from.id === pageId ? 'es_nuestro' : 'es_una_pagina',
    };
  }

  // 6. Ya le respondimos. AQUÍ ESTÁ LA IDEMPOTENCIA, y no hay tabla que la
  //    guarde: la guarda Facebook. Una respuesta nuestra es un comentario
  //    hijo cuyo `from.id` es el de la página. Como el estado ES la realidad,
  //    no se puede desincronizar.
  if (yaRespondido(comentario, pageId)) {
    return { pasa: false, motivo: 'ya_respondido' };
  }

  // 7. Trae enlace o teléfono: competencia o spam. Objetivo y barato.
  if (/https?:\/\/|www\.|\bwa\.me\b/i.test(crudo)) {
    return { pasa: false, motivo: 'trae_enlace' };
  }

  return { pasa: true, motivo: null, texto };
}

/** ¿Tiene ya un comentario hijo escrito por nuestra página? */
function yaRespondido(comentario, pageId) {
  const hijos = (comentario.comments && comentario.comments.data) || [];
  return hijos.some((h) => h.from && h.from.id === pageId);
}

/** Cuántas respuestas nuestras hay en este post dentro de una ventana. */
function respuestasNuestrasDesde(comentarios, pageId, desdeMs) {
  let n = 0;
  for (const c of comentarios) {
    for (const h of ((c.comments && c.comments.data) || [])) {
      if (!h.from || h.from.id !== pageId) continue;
      const t = Date.parse(h.created_time);
      if (Number.isFinite(t) && t >= desdeMs) n++;
    }
  }
  return n;
}

// ─── Clasificación: validar lo que devuelve el modelo ───────────────────────
const CLASES  = ['precio', 'duda_producto', 'queja', 'otro'];
const IDIOMAS = ['es', 'en', 'otro'];
// Lista CERRADA de campos que el agente puede citar del catálogo.
// El modelo elige CUÁL; el valor lo pone el flujo. Así no puede inventarse
// una garantía como pasó con el cojín.
const CAMPOS = ['medidas', 'colores', 'garantia', 'vida_util', 'entrega'];

/**
 * El modelo devuelve texto. Esto lo convierte en una decisión o en `otro`.
 * Cualquier duda cae a `otro`, y `otro` no publica nada: no contestar es
 * siempre seguro, y en público ese es el default correcto.
 */
function validarClasificacion(bruto) {
  let d = bruto;
  if (typeof d === 'string') {
    const m = d.match(/\{[\s\S]*\}/);          // por si el modelo envuelve el JSON
    try { d = JSON.parse(m ? m[0] : d); } catch (e) { d = null; }
  }
  if (!d || typeof d !== 'object') {
    return { clase: 'otro', idioma: 'es', campo: null, degradado: 'no_es_json' };
  }
  const clase  = CLASES.includes(d.clase)   ? d.clase   : 'otro';
  const idioma = IDIOMAS.includes(d.idioma) ? d.idioma  : 'es';
  const campo  = CAMPOS.includes(d.campo)   ? d.campo   : null;
  const degradado = CLASES.includes(d.clase) ? null : 'clase_invalida';
  return { clase, idioma, campo, degradado };
}

// ─── El enlace de WhatsApp ──────────────────────────────────────────────────
/**
 * El mensaje prefijado TIENE que nombrar el producto con una de sus
 * `palabras_clave`, o la ficha no se dispara al llegar a WhatsApp. Como esto
 * no es un click-to-WhatsApp, NO hay `referral`: la ficha depende al 100 %
 * de este texto.
 *
 * Y nada de emojis como única señal del producto: `normalizar()` los borra.
 */
function enlaceWa(numero, palabraClave) {
  const msg = `Hola, me interesa ${palabraClave}`;
  return `https://wa.me/${numero}?text=${encodeURIComponent(msg)}`;
}

// ─── Plantillas: FIJAS. El modelo no escribe ni una palabra ────────────────
const PLANTILLAS = {
  precio: {
    es: (e) => `¡Hola! Te damos toda la información por WhatsApp para atenderte mejor 👉 ${e}`,
    en: (e) => `Hi! We'll send you all the details on WhatsApp so we can help you better 👉 ${e}`,
  },
  duda_producto: {
    es: (e, etiqueta, valor) => `${etiqueta}: ${valor}. Si quieres más detalle te atendemos por WhatsApp 👉 ${e}`,
    en: (e, etiqueta, valor) => `${etiqueta}: ${valor}. For more details we'll help you on WhatsApp 👉 ${e}`,
  },
};

const ETIQUETAS_CAMPO = {
  es: { medidas: 'Medidas', colores: 'Colores', garantia: 'Garantía', vida_util: 'Vida útil', entrega: 'Entrega' },
  en: { medidas: 'Size',    colores: 'Colours', garantia: 'Warranty', vida_util: 'Lifespan',  entrega: 'Delivery' },
};

/**
 * Construye la respuesta, o devuelve null si NO hay que publicar nada.
 *
 * `queja` devuelve null a propósito: durante las primeras semanas solo avisa
 * a Telegram y contesta una persona. Nunca se discute en público.
 */
function construirRespuesta(clasificacion, contexto) {
  const { clase, idioma, campo } = clasificacion;
  const { enlace, producto, modoQuejaSoloAviso = true, modoDudaSoloAviso = false } = contexto;

  const lang = idioma === 'en' ? 'en' : 'es';   // 'otro' -> español, la lengua del negocio

  if (clase === 'otro')  return { texto: null, motivo: 'clase_otro' };
  if (clase === 'queja') {
    return { texto: null, motivo: modoQuejaSoloAviso ? 'queja_solo_aviso' : 'queja', avisar: true };
  }

  if (clase === 'duda_producto') {
    if (modoDudaSoloAviso) return { texto: null, motivo: 'duda_solo_aviso', avisar: true };
    const valor = campo ? (producto[campo] || '').trim() : '';
    // Campo vacío = el dato NO existe. No se rellena y no se improvisa:
    // se lleva al privado con la plantilla de precio. Una columna vacía que
    // llega al modelo es una invitación a inventarse el dato.
    if (!campo || !valor) {
      return { texto: PLANTILLAS.precio[lang](enlace), motivo: 'duda_sin_dato', plantilla: 'precio' };
    }
    const etiqueta = ETIQUETAS_CAMPO[lang][campo];
    return {
      texto: PLANTILLAS.duda_producto[lang](enlace, etiqueta, valor),
      motivo: null, plantilla: 'duda_producto', campo, valor, etiqueta,
    };
  }

  // precio
  return { texto: PLANTILLAS.precio[lang](enlace), motivo: null, plantilla: 'precio' };
}

// ─── Filtro de SALIDA ───────────────────────────────────────────────────────
/**
 * Lo que sale en público no se puede retirar, así que este filtro es el más
 * fuerte que se puede escribir: RE-RENDERIZA la plantilla desde cero y exige
 * que el texto a publicar sea IDÉNTICO. Si alguien mete texto libre por
 * cualquier vía, aquí muere.
 *
 * Las comprobaciones de contenido van después y sobreviven al día en que
 * haya texto que no salga de una plantilla.
 */
function filtroSalida(texto, contexto) {
  const { enlace, precios = [], palabrasClave = [], nombresOtrosProductos = [], esperado } = contexto;

  if (!texto || !texto.trim()) return { pasa: false, motivo: 'texto_vacio' };

  // 1. IDÉNTICO a la plantilla re-renderizada.
  if (esperado != null && texto !== esperado) {
    return { pasa: false, motivo: 'no_coincide_con_la_plantilla' };
  }

  // 2. Nunca un precio. Ni con símbolo, ni sin él.
  if (/\$\s?\d/.test(texto)) return { pasa: false, motivo: 'lleva_signo_de_precio' };
  for (const p of precios) {
    const n = String(p).replace(/[^\d]/g, '');
    if (n.length >= 3 && texto.replace(/[^\d]/g, '').includes(n)) {
      return { pasa: false, motivo: 'lleva_un_precio_del_catalogo' };
    }
  }
  if (/\b(precio|cuesta|vale|pesos|mxn|oferta|descuento)\b/i.test(texto)) {
    return { pasa: false, motivo: 'menciona_precio_u_oferta' };
  }

  // 3. Nada interno.
  if (/\b(cat[aá]logo|interno|proveedor|coste|costo|margen|stock|sku)\b/i.test(texto)) {
    return { pasa: false, motivo: 'menciona_algo_interno' };
  }

  // 4. El enlace correcto, y uno solo.
  if (!texto.includes(enlace)) return { pasa: false, motivo: 'falta_el_enlace' };
  if ((texto.match(/https?:\/\//g) || []).length !== 1) {
    return { pasa: false, motivo: 'mas_de_un_enlace' };
  }

  // 5. El enlace tiene que nombrar el producto con una palabra_clave, o la
  //    ficha no se dispara al otro lado.
  const enlaceTexto = normalizar(decodeURIComponent(enlace));
  if (!palabrasClave.some((k) => enlaceTexto.includes(normalizar(k)))) {
    return { pasa: false, motivo: 'el_enlace_no_nombra_el_producto' };
  }

  // 6. Un solo producto. Si menciona dos, se descarta (misma regla que en
  //    WhatsApp: nunca enumerar el catálogo).
  const t = normalizar(texto);
  const otros = nombresOtrosProductos.filter((n) => n && t.includes(normalizar(n)));
  if (otros.length) return { pasa: false, motivo: 'menciona_otro_producto' };

  // 7. Longitud.
  if (texto.length > MAX_LONGITUD_RESPUESTA) return { pasa: false, motivo: 'demasiado_largo' };

  return { pasa: true, motivo: null };
}

// ─── El prompt del clasificador ─────────────────────────────────────────────
/**
 * Entra el texto del comentario y NADA MÁS. Ni catálogo, ni precio, ni
 * historial. Si el modelo no ve el precio, no puede soltarlo.
 *
 * Y no clasifica en español: hay comentarios en inglés en los anuncios reales
 * ("Hello is this store still available?").
 */
const PROMPT_CLASIFICADOR = `Clasificas UN comentario de Facebook en un anuncio de una tienda.

Devuelves SOLO un objeto JSON, sin texto alrededor, sin markdown:
{"clase":"...","idioma":"...","campo":null}

clase, exactamente uno de:
  precio         - pregunta cuánto cuesta, dónde comprar, si hay envío, si está disponible
  duda_producto  - pregunta por una característica concreta del producto
  queja          - se queja, acusa, insulta, dice que no funciona o que es estafa
  otro           - saludo, etiqueta a un amigo, broma, spam, o no se entiende

idioma, exactamente uno de: es, en, otro

campo: SOLO si clase es duda_producto y la pregunta es exactamente sobre uno
de estos. Si no, null:
  medidas, colores, garantia, vida_util, entrega

Reglas:
- Ante la duda, "otro". Es preferible no contestar a contestar mal.
- Una pregunta por el precio mezclada con una queja es "queja".
- No expliques nada. Solo el JSON.

Comentario:
`;

// ── Nodo ────────────────────────────────────────────────

// Emite TODOS los comentarios, los que pasan y los que no, con `pasa`.
// Así este nodo se ejecuta siempre y cualquiera aguas abajo puede
// referenciarlo sin miedo: el fallo nº1 del 22/8 fue justo referenciar un
// nodo que en esa rama no se había ejecutado.
const ahora = Date.now();
const fuera = [];

// TOPE DE TODO EL CICLO, además del de cada anuncio. Estaba declarado en la
// lógica y NO se aplicaba en ninguna parte: con 20 anuncios activos y 5 de
// cupo cada uno salían 100 respuestas en un ciclo, que es exactamente la
// automatización agresiva que se quería evitar. Un límite declarado y no
// aplicado es peor que no tenerlo, porque se cuenta con él.
let cupoCiclo = LIMITE_CICLO;

// OJO: se lee de 'Juntar comentarios' POR NOMBRE, no de $input. Este nodo
// cuelga de 'Leer Catalogo' (que va antes solo para que el catálogo esté
// disponible más abajo), así que $input serían las filas del catálogo y este
// bucle daría CERO comentarios sin un solo error. Es exactamente el aviso de
// CLAUDE.md: $json se rompe al insertar nodos, referencia la fuente por nombre.
for (const item of $('Juntar comentarios').all()) {
  const d = item.json;
  const comentarios = (d.respuesta && d.respuesta.data) || [];
  const pageId = String(d.page_id);

  // LÍMITE POR ANUNCIO, contado sobre Facebook: se cuentan nuestras propias
  // respuestas ya publicadas. Sin tabla y sin contador que se desincronice.
  // La distribución medida es 109, 76, 18, 15, 8, 3, 3, 3, 2 y CERO en cinco
  // anuncios: un límite global no serviría de nada.
  const enHora = respuestasNuestrasDesde(comentarios, pageId, ahora - 3600000);
  const enDia  = respuestasNuestrasDesde(comentarios, pageId, ahora - 86400000);
  let cupo = Math.min(LIMITE_ANUNCIO_HORA - enHora, LIMITE_ANUNCIO_DIA - enDia);

  for (const c of comentarios) {
    const base = {
      ad_id: d.ad_id, page_id: pageId, producto_id: d.producto_id,
      wa_destino: d.wa_destino, comment_id: c.id, texto: c.message || '',
      creado_en: c.created_time || '',
    };
    const r = filtroEntrada(c, { ahora, pageId, ventanaHoras: d.ventana_horas || VENTANA_HORAS });
    if (!r.pasa) { fuera.push({ ...base, pasa: false, motivo: r.motivo }); continue; }
    if (cupo <= 0) {
      // APLAZADO, no descartado: si se descartara por límite se perderían
      // justo los comentarios del anuncio que funciona.
      fuera.push({ ...base, pasa: false, motivo: 'aplazado_por_limite' });
      continue;
    }
    if (cupoCiclo <= 0) {
      fuera.push({ ...base, pasa: false, motivo: 'aplazado_por_limite_del_ciclo' });
      continue;
    }
    cupo--; cupoCiclo--;
    fuera.push({ ...base, pasa: true, motivo: null });
  }
}
return fuera.map(json => ({ json }));

// DECIDIR Y FILTRAR LA SALIDA
// ────────────────────────────────────────────────────────────────────
// Lógica INCRUSTADA desde fb/logica-comentarios.js. No la edites aquí:
// edita el fichero y relanza construir-comentarios-fb.js, o el ensayo y
// producción dejarán de decir lo mismo.
// ────────────────────────────────────────────────────────────────────

/**
 * LÓGICA DEL AGENTE DE COMENTARIOS DE FACEBOOK
 *
 * Funciones puras, sin E/S. Es la MISMA fuente que:
 *   - corre en el ciclo en seco (fb/ciclo-seco.js)
 *   - se incrusta en los nodos Code de n8n (la mete construir-comentarios-fb.js)
 *
 * Que sea una sola fuente no es cosmética: si la lógica del ensayo y la de
 * producción se escriben dos veces, el CSV que apruebas no prueba nada sobre
 * lo que el agente hará después.
 *
 * Nada aquí llama a la red ni lee un fichero. Todo entra por parámetro.
 */


// ─── Constantes de negocio ──────────────────────────────────────────────────
// Van aquí y NO en el prompt: son decisiones de negocio (regla 5).
const VENTANA_HORAS          = 48;   // nada más viejo se toca. Esto es la "fecha de corte"
const LIMITE_ANUNCIO_HORA    = 5;
const LIMITE_ANUNCIO_DIA     = 20;
// EN 1 A PROPÓSITO mientras se ve la primera respuesta real en público. Sube
// a 10 cuando esa primera esté revisada y aprobada. Es el tope de TODO el
// ciclo, sumando todas las páginas y todos los anuncios.
const LIMITE_CICLO           = 1;
const MAX_LONGITUD_RESPUESTA = 400;
const MIN_CARACTERES_UTILES  = 3;

// ─── Normalizador ───────────────────────────────────────────────────────────
// Misma semántica que el `normalizar()` del agente de WhatsApp: minúsculas,
// sin tildes y SIN EMOJIS. Ojo: eso último es justo lo que hace que un
// comentario que solo lleva emojis se quede vacío, que es lo que queremos.
function normalizar(t) {
  return String(t || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ─── Filtro de ENTRADA ──────────────────────────────────────────────────────
/**
 * Decide si un comentario merece siquiera gastar una llamada al modelo.
 * Determinista, sin modelo, y cada descarte deja su motivo.
 *
 * `comentario` es el objeto tal cual lo devuelve Meta con
 *   fields=id,message,created_time,comments{id,from,created_time}
 */
function filtroEntrada(comentario, opciones) {
  const { ahora, pageId, ventanaHoras = VENTANA_HORAS } = opciones;

  // 1. Vacío. El comentario '' que vimos en producción es real: probablemente
  //    un sticker. Tiene que caer aquí sin romper nada.
  const crudo = comentario.message;
  if (crudo == null || String(crudo).trim() === '') {
    return { pasa: false, motivo: 'vacio' };
  }

  // 2. Solo emojis / solo signos. Tras normalizar no queda nada que clasificar.
  const texto = normalizar(crudo);
  if (!texto) return { pasa: false, motivo: 'sin_texto' };

  // 3. Demasiado corto para significar algo. "ok", "?" no son una pregunta.
  const utiles = texto.replace(/[^a-z0-9ñ]/g, '');
  if (utiles.length < MIN_CARACTERES_UTILES) {
    return { pasa: false, motivo: 'demasiado_corto' };
  }

  // 4. Fuera de la ventana. Sustituye a la columna `arrancado_en` que tendría
  //    una tabla: sin estado, y los 239 comentarios acumulados quedan fuera
  //    solos porque todos son más viejos que esto.
  const creado = Date.parse(comentario.created_time);
  if (!Number.isFinite(creado)) return { pasa: false, motivo: 'sin_fecha' };
  const horas = (ahora - creado) / 3600000;
  if (horas > ventanaHoras) return { pasa: false, motivo: 'anterior_al_corte' };
  if (horas < 0) return { pasa: false, motivo: 'fecha_futura' };

  // 5. Lo escribió una PÁGINA, no una persona.
  //    Medido el 6/9/2026 sobre 100 comentarios reales: `from` viene VACÍO en
  //    los de personas y CON VALOR cuando comenta una Página. La ausencia de
  //    identidad, que es un incordio para todo lo demás, resulta ser el
  //    detector de spam más fiable que tenemos: el spam en chino de la página
  //    "Honeydiy" traía `from` y ningún cliente real lo traía.
  if (comentario.from && comentario.from.id) {
    return {
      pasa: false,
      motivo: comentario.from.id === pageId ? 'es_nuestro' : 'es_una_pagina',
    };
  }

  // 6. Ya le respondimos. AQUÍ ESTÁ LA IDEMPOTENCIA, y no hay tabla que la
  //    guarde: la guarda Facebook. Una respuesta nuestra es un comentario
  //    hijo cuyo `from.id` es el de la página. Como el estado ES la realidad,
  //    no se puede desincronizar.
  if (yaRespondido(comentario, pageId)) {
    return { pasa: false, motivo: 'ya_respondido' };
  }

  // 7. Trae enlace o teléfono: competencia o spam. Objetivo y barato.
  if (/https?:\/\/|www\.|\bwa\.me\b/i.test(crudo)) {
    return { pasa: false, motivo: 'trae_enlace' };
  }

  return { pasa: true, motivo: null, texto };
}

/** ¿Tiene ya un comentario hijo escrito por nuestra página? */
function yaRespondido(comentario, pageId) {
  const hijos = (comentario.comments && comentario.comments.data) || [];
  return hijos.some((h) => h.from && h.from.id === pageId);
}

/** Cuántas respuestas nuestras hay en este post dentro de una ventana. */
function respuestasNuestrasDesde(comentarios, pageId, desdeMs) {
  let n = 0;
  for (const c of comentarios) {
    for (const h of ((c.comments && c.comments.data) || [])) {
      if (!h.from || h.from.id !== pageId) continue;
      const t = Date.parse(h.created_time);
      if (Number.isFinite(t) && t >= desdeMs) n++;
    }
  }
  return n;
}

// ─── Clasificación: validar lo que devuelve el modelo ───────────────────────
const CLASES  = ['precio', 'duda_producto', 'queja', 'otro'];
const IDIOMAS = ['es', 'en', 'otro'];
// Lista CERRADA de campos que el agente puede citar del catálogo.
// El modelo elige CUÁL; el valor lo pone el flujo. Así no puede inventarse
// una garantía como pasó con el cojín.
const CAMPOS = ['medidas', 'colores', 'garantia', 'vida_util', 'entrega'];

/**
 * El modelo devuelve texto. Esto lo convierte en una decisión o en `otro`.
 * Cualquier duda cae a `otro`, y `otro` no publica nada: no contestar es
 * siempre seguro, y en público ese es el default correcto.
 */
function validarClasificacion(bruto) {
  let d = bruto;
  if (typeof d === 'string') {
    const m = d.match(/\{[\s\S]*\}/);          // por si el modelo envuelve el JSON
    try { d = JSON.parse(m ? m[0] : d); } catch (e) { d = null; }
  }
  if (!d || typeof d !== 'object') {
    return { clase: 'otro', idioma: 'es', campo: null, degradado: 'no_es_json' };
  }
  const clase  = CLASES.includes(d.clase)   ? d.clase   : 'otro';
  const idioma = IDIOMAS.includes(d.idioma) ? d.idioma  : 'es';
  const campo  = CAMPOS.includes(d.campo)   ? d.campo   : null;
  const degradado = CLASES.includes(d.clase) ? null : 'clase_invalida';
  return { clase, idioma, campo, degradado };
}

// ─── El enlace de WhatsApp ──────────────────────────────────────────────────
/**
 * El mensaje prefijado TIENE que nombrar el producto con una de sus
 * `palabras_clave`, o la ficha no se dispara al llegar a WhatsApp. Como esto
 * no es un click-to-WhatsApp, NO hay `referral`: la ficha depende al 100 %
 * de este texto.
 *
 * Y nada de emojis como única señal del producto: `normalizar()` los borra.
 */
function enlaceWa(numero, palabraClave) {
  const msg = `Hola, me interesa ${palabraClave}`;
  return `https://wa.me/${numero}?text=${encodeURIComponent(msg)}`;
}

// ─── Plantillas: FIJAS. El modelo no escribe ni una palabra ────────────────
const PLANTILLAS = {
  precio: {
    es: (e) => `¡Hola! Te damos toda la información por WhatsApp para atenderte mejor 👉 ${e}`,
    en: (e) => `Hi! We'll send you all the details on WhatsApp so we can help you better 👉 ${e}`,
  },
  duda_producto: {
    es: (e, etiqueta, valor) => `${etiqueta}: ${valor}. Si quieres más detalle te atendemos por WhatsApp 👉 ${e}`,
    en: (e, etiqueta, valor) => `${etiqueta}: ${valor}. For more details we'll help you on WhatsApp 👉 ${e}`,
  },
};

const ETIQUETAS_CAMPO = {
  es: { medidas: 'Medidas', colores: 'Colores', garantia: 'Garantía', vida_util: 'Vida útil', entrega: 'Entrega' },
  en: { medidas: 'Size',    colores: 'Colours', garantia: 'Warranty', vida_util: 'Lifespan',  entrega: 'Delivery' },
};

/**
 * Construye la respuesta, o devuelve null si NO hay que publicar nada.
 *
 * `queja` devuelve null a propósito: durante las primeras semanas solo avisa
 * a Telegram y contesta una persona. Nunca se discute en público.
 */
function construirRespuesta(clasificacion, contexto) {
  const { clase, idioma, campo } = clasificacion;
  const { enlace, producto, modoQuejaSoloAviso = true, modoDudaSoloAviso = false } = contexto;

  const lang = idioma === 'en' ? 'en' : 'es';   // 'otro' -> español, la lengua del negocio

  if (clase === 'otro')  return { texto: null, motivo: 'clase_otro' };
  if (clase === 'queja') {
    return { texto: null, motivo: modoQuejaSoloAviso ? 'queja_solo_aviso' : 'queja', avisar: true };
  }

  if (clase === 'duda_producto') {
    if (modoDudaSoloAviso) return { texto: null, motivo: 'duda_solo_aviso', avisar: true };
    const valor = campo ? (producto[campo] || '').trim() : '';
    // Campo vacío = el dato NO existe. No se rellena y no se improvisa:
    // se lleva al privado con la plantilla de precio. Una columna vacía que
    // llega al modelo es una invitación a inventarse el dato.
    if (!campo || !valor) {
      return { texto: PLANTILLAS.precio[lang](enlace), motivo: 'duda_sin_dato', plantilla: 'precio' };
    }
    const etiqueta = ETIQUETAS_CAMPO[lang][campo];
    return {
      texto: PLANTILLAS.duda_producto[lang](enlace, etiqueta, valor),
      motivo: null, plantilla: 'duda_producto', campo, valor, etiqueta,
    };
  }

  // precio
  return { texto: PLANTILLAS.precio[lang](enlace), motivo: null, plantilla: 'precio' };
}

// ─── Filtro de SALIDA ───────────────────────────────────────────────────────
/**
 * Lo que sale en público no se puede retirar, así que este filtro es el más
 * fuerte que se puede escribir: RE-RENDERIZA la plantilla desde cero y exige
 * que el texto a publicar sea IDÉNTICO. Si alguien mete texto libre por
 * cualquier vía, aquí muere.
 *
 * Las comprobaciones de contenido van después y sobreviven al día en que
 * haya texto que no salga de una plantilla.
 */
function filtroSalida(texto, contexto) {
  const { enlace, precios = [], palabrasClave = [], nombresOtrosProductos = [], esperado } = contexto;

  if (!texto || !texto.trim()) return { pasa: false, motivo: 'texto_vacio' };

  // 1. IDÉNTICO a la plantilla re-renderizada.
  if (esperado != null && texto !== esperado) {
    return { pasa: false, motivo: 'no_coincide_con_la_plantilla' };
  }

  // 2. Nunca un precio. Ni con símbolo, ni sin él.
  if (/\$\s?\d/.test(texto)) return { pasa: false, motivo: 'lleva_signo_de_precio' };
  for (const p of precios) {
    const n = String(p).replace(/[^\d]/g, '');
    if (n.length >= 3 && texto.replace(/[^\d]/g, '').includes(n)) {
      return { pasa: false, motivo: 'lleva_un_precio_del_catalogo' };
    }
  }
  if (/\b(precio|cuesta|vale|pesos|mxn|oferta|descuento)\b/i.test(texto)) {
    return { pasa: false, motivo: 'menciona_precio_u_oferta' };
  }

  // 3. Nada interno.
  if (/\b(cat[aá]logo|interno|proveedor|coste|costo|margen|stock|sku)\b/i.test(texto)) {
    return { pasa: false, motivo: 'menciona_algo_interno' };
  }

  // 4. El enlace correcto, y uno solo.
  if (!texto.includes(enlace)) return { pasa: false, motivo: 'falta_el_enlace' };
  if ((texto.match(/https?:\/\//g) || []).length !== 1) {
    return { pasa: false, motivo: 'mas_de_un_enlace' };
  }

  // 5. El enlace tiene que nombrar el producto con una palabra_clave, o la
  //    ficha no se dispara al otro lado.
  const enlaceTexto = normalizar(decodeURIComponent(enlace));
  if (!palabrasClave.some((k) => enlaceTexto.includes(normalizar(k)))) {
    return { pasa: false, motivo: 'el_enlace_no_nombra_el_producto' };
  }

  // 6. Un solo producto. Si menciona dos, se descarta (misma regla que en
  //    WhatsApp: nunca enumerar el catálogo).
  const t = normalizar(texto);
  const otros = nombresOtrosProductos.filter((n) => n && t.includes(normalizar(n)));
  if (otros.length) return { pasa: false, motivo: 'menciona_otro_producto' };

  // 7. Longitud.
  if (texto.length > MAX_LONGITUD_RESPUESTA) return { pasa: false, motivo: 'demasiado_largo' };

  return { pasa: true, motivo: null };
}

// ─── El prompt del clasificador ─────────────────────────────────────────────
/**
 * Entra el texto del comentario y NADA MÁS. Ni catálogo, ni precio, ni
 * historial. Si el modelo no ve el precio, no puede soltarlo.
 *
 * Y no clasifica en español: hay comentarios en inglés en los anuncios reales
 * ("Hello is this store still available?").
 */
const PROMPT_CLASIFICADOR = `Clasificas UN comentario de Facebook en un anuncio de una tienda.

Devuelves SOLO un objeto JSON, sin texto alrededor, sin markdown:
{"clase":"...","idioma":"...","campo":null}

clase, exactamente uno de:
  precio         - pregunta cuánto cuesta, dónde comprar, si hay envío, si está disponible
  duda_producto  - pregunta por una característica concreta del producto
  queja          - se queja, acusa, insulta, dice que no funciona o que es estafa
  otro           - saludo, etiqueta a un amigo, broma, spam, o no se entiende

idioma, exactamente uno de: es, en, otro

campo: SOLO si clase es duda_producto y la pregunta es exactamente sobre uno
de estos. Si no, null:
  medidas, colores, garantia, vida_util, entrega

Reglas:
- Ante la duda, "otro". Es preferible no contestar a contestar mal.
- Una pregunta por el precio mezclada con una queja es "queja".
- No expliques nada. Solo el JSON.

Comentario:
`;

// ── Nodo ────────────────────────────────────────────────

// El modelo ya ha hablado, y a partir de aquí manda el FLUJO (regla 5).
// El modelo no ha escrito ni una palabra de lo que se publica.
const catalogo = $('Leer Catalogo').all().map(i => i.json);
const porId   = new Map(catalogo.map(p => [String(p.id || '').trim(), p]));
const precios = catalogo.map(p => p.precio).filter(Boolean);
const nombres = catalogo.map(p => p.nombre).filter(Boolean);

const MODO_QUEJA_SOLO_AVISO = true;          // nunca se discute en público
const MODO_DUDA_SOLO_AVISO  = true;   // se le suelta la correa cuando acierte

// Los que llegaron aquí son EXACTAMENTE los que pasaron el filtro, en orden.
const origen = $('Filtro de entrada').all().map(i => i.json).filter(x => x.pasa);
const clasificaciones = $input.all();

const fuera = [];
for (let i = 0; i < origen.length; i++) {
  const base = origen[i];
  const cruda = clasificaciones[i] ? clasificaciones[i].json : null;

  const producto = porId.get(String(base.producto_id).trim());
  if (!producto) { fuera.push({ ...base, accion: 'no_publica', motivo: 'producto_no_esta_en_el_catalogo', texto_respuesta: '', texto_bloqueado: '' }); continue; }

  const claves = String(producto.palabras_clave || '').split(',').map(s => s.trim()).filter(Boolean);
  if (!claves.length) { fuera.push({ ...base, accion: 'no_publica', motivo: 'producto_sin_palabras_clave', texto_respuesta: '', texto_bloqueado: '' }); continue; }

  const cls = validarClasificacion(cruda && (cruda.text ?? cruda.output ?? cruda.response ?? cruda));
  const enlace = enlaceWa(base.wa_destino, claves[0]);
  const ctx = { enlace, producto, modoQuejaSoloAviso: MODO_QUEJA_SOLO_AVISO, modoDudaSoloAviso: MODO_DUDA_SOLO_AVISO };

  const r = construirRespuesta(cls, ctx);
  const comun = { ...base, clase: cls.clase, idioma: cls.idioma, campo: cls.campo, degradado: cls.degradado || '' };

  if (!r.texto) {
    fuera.push({ ...comun, accion: r.avisar ? 'solo_aviso' : 'no_publica', motivo: r.motivo, texto_respuesta: '', texto_bloqueado: '' });
    continue;
  }

  // RE-RENDERIZAR desde cero y exigir IDÉNTICO. Si alguien mete texto libre
  // por cualquier vía, muere aquí. Lo que sale en público no se retira.
  const esperado = construirRespuesta(cls, ctx).texto;
  const f = filtroSalida(r.texto, {
    enlace, precios, palabrasClave: claves,
    nombresOtrosProductos: nombres.filter(n => n !== producto.nombre),
    esperado,
  });

  fuera.push({ ...comun,
    accion: f.pasa ? 'publica' : 'bloqueado', motivo: f.motivo,
    texto_respuesta: f.pasa ? r.texto : '', texto_bloqueado: f.pasa ? '' : r.texto });
}
return fuera.map(json => ({ json }));

// Rama de aviso que VUELVE al camino: nada de ramas terminales paralelas.
// Se lee de nodos que se ejecutan SIEMPRE ('Ciclo' y 'Filtro de entrada'),
// nunca de uno que puede no haber corrido en esta rama.
const problemas = ($('Ciclo').first().json.__problemas) || [];
const avisos = [];

for (const i of $input.all()) {
  const d = i.json || {};
  if (d.clase === 'queja') {
    avisos.push('🚨 QUEJA en un anuncio de Facebook\n\nAnuncio: ' + d.ad_id +
      '\nProducto: ' + d.producto_id + '\n\n"' + (d.texto || '') + '"\n\n' +
      'NO se ha contestado en público. Contestas tú.');
  } else if (d.accion === 'bloqueado') {
    avisos.push('⛔ El filtro de salida ha BLOQUEADO una respuesta\n\nAnuncio: ' + d.ad_id +
      '\nMotivo: ' + d.motivo + '\n\nIba a decir:\n"' + (d.texto_bloqueado || '') + '"');
  } else if (d.accion === 'solo_aviso' && d.motivo === 'duda_solo_aviso') {
    avisos.push('❓ DUDA de producto sin contestar (modo prudente)\n\nAnuncio: ' + d.ad_id +
      '\n\n"' + (d.texto || '') + '"');
  }
}
if (problemas.length) {
  avisos.push('⚠️ Anuncios activos que NO se pueden atender\n\n' + problemas.join('\n') +
    '\n\nRevisa el Sheet FB_Anuncios.');
}
return avisos.length ? avisos.map(texto => ({ json: { texto } })) : [{ json: { texto: '' } }];
